 if(Object.values(raw).some(x=>x&&typeof x==='object'&&'select_type'in x))return Object.entries(raw).map(([key,x])=>({key,label:x.name||'Equipment',mode:x.select_type,defaults:x.default||[],options:x.options||[],strict:x.replacement_mode==='strict'}));
