 const groupTypes=()=>{let groups=new Map;for(let t of rows()){let key=[t.gang_type_id||t.gangType||'',name(t),t.fighter_variant||''].join('|');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(t)}typeGroups=[...groups.values()];return typeGroups};
