const priorEditFighter=editFighter;editFighter=function(f){if(f)return priorEditFighter(f);recruit('fighter')};
vehicleForm=function(v){if(v)return formModal('Edit Vehicle',text('name','Vehicle Name *',v.name,'required')+text('type','Vehicle Type',v.type)+text('cost','Cost (credits)',v.cost,'type="number" min="0"')+textarea('notes','Notes',v.notes),x=>{Object.assign(v,{...x,cost:Math.max(0,num(x.cost))});save()},'Save Changes');recruit('vehicle')};

function gangLogs(g){showModal('Gang Logs',`<div class="gp-logs">${(g.logs||[]).map(x=>`<article><time>${esc(new Date(x.at).toLocaleString())}</time><p>${esc(x.text)}</p></article>`).join('')||'<p class="muted">No logs recorded.</p>'}</div>`,'Close',()=>true)}
function copyGangDialog(g){formModal('Copy Gang','<p class="wide muted">Choose a name for the new gang.</p>'+text('name','New gang name',g.name+' copy',`required placeholder="${esc(g.name)} copy"`),v=>{
 const clone=JSON.parse(JSON.stringify(g)),mapping=new Map([[g.id,id()]]),instanceArrays=['fighters','vehicles','stash','equipment','effects','injuries','advancements','loadouts','xpHistory','ooaRecords'];
 function collect(obj){if(!obj||typeof obj!=='object')return;for(const key of instanceArrays)for(const row of Array.isArray(obj[key])?obj[key]:[]){if(row.id&&!mapping.has(row.id))mapping.set(row.id,id());collect(row)}}collect(clone);
 function remap(obj){if(Array.isArray(obj))return obj.map(remap);if(obj&&typeof obj==='object')return Object.fromEntries(Object.entries(obj).map(([k,value])=>[k,remap(value)]));return typeof obj==='string'&&mapping.has(obj)?mapping.get(obj):obj}
 const copied=remap(clone);copied.name=v.name.trim();copied.logs=[];copied.privateNotes='';copied.createdAt=now();copied.updatedAt=now();data.gangs.push(copied);data.selectedGang=copied.id;data.view='gang';data.tab='fighters';log(copied,'Gang copied.');save();
 },'Copy');bindDisabled(document.querySelector('#modal-form'),()=>!!document.querySelector('[name="name"]').value.trim())}

function shareGang(g,reviewed=false){if(!reviewed&&window.MMRosterValidation)return MMRosterValidation.reviewBefore(g,()=>shareGang(g,true));let snapshot={format:'munda-manager-gang',version:1,gang:JSON.parse(JSON.stringify(g))};showModal('Share Gang',`<p class="mm-note">Share this gang file with another player to import the roster.</p><div class="gp-share-options"><button class="btn" data-gp="download-gang">Download Gang JSON</button><button class="btn" data-gp="copy-gang-link">Copy Link</button></div><p id="gp-share-feedback" class="mm-note"></p>`,'Close',()=>true);document.querySelector('[data-gp="download-gang"]').onclick=()=>{let a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'}));a.href=url;a.download=g.name.replace(/[^\w가-힣-]/g,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};document.querySelector('[data-gp="copy-gang-link"]').onclick=async()=>{let text=location.origin+'/gang/'+encodeURIComponent(g.id);try{await navigator.clipboard.writeText(text);document.querySelector('#gp-share-feedback').textContent='Link copied. Shared viewers need campaign access.'}catch{document.querySelector('#gp-share-feedback').textContent=text}}}

